mapper.select:
SELECT id, group_id, artifact_id, version, classifier, extension, coordinate, relative_path,
       sha256, original_filename, size_bytes, uploaded_by, created_at, updated_at
FROM plugin_local_dependency_artifact
WHERE group_id = #{groupId}
  AND artifact_id = #{artifactId}
  AND version = #{version}
  AND classifier = #{classifier}
  AND extension = #{extension}
